#!/usr/bin/env bash
# Prints the wiki "Releases" page (Markdown) built from the repository's GitHub releases.
# Needs GITHUB_REPOSITORY and GH_TOKEN; uses `gh` and `jq` (both preinstalled on runners).
set -euo pipefail

repo="${GITHUB_REPOSITORY:?GITHUB_REPOSITORY is not set}"
releases="$(gh api "repos/${repo}/releases?per_page=100" --paginate | jq -s 'add // [] | map(select(.draft | not))')"

cat <<EOF
# Releases

> This page is generated by the [Release workflow](https://github.com/${repo}/actions/workflows/release.yml)
> after each approved release. Edits made here are overwritten.

Every download needs the data files from **your own copy** of Blood (1997): OpenBlood ships
no game content. See [Installation](Installation) for which files to copy.

EOF

if [ "$(jq length <<<"$releases")" -eq 0 ]; then
  echo "No releases have been published yet."
  exit 0
fi

jq -r '
  def mb: if . < 1048576 then ((. / 1024 | ceil | tostring) + " KB")
          else ((. / 1048576 * 10 | round) / 10 | tostring) + " MB" end;
  def short: sub("^openblood-[^-]+-"; "");
  .[0] as $l
  | "## Latest: [\($l.tag_name)](\($l.html_url))",
    "",
    "Published \($l.published_at[0:10]).",
    "",
    "| Download | Size |",
    "| --- | --- |",
    ($l.assets[] | "| [\(.name)](\(.browser_download_url)) | \(.size | mb) |"),
    "",
    "## All releases",
    "",
    "| Version | Date | Downloads |",
    "| --- | --- | --- |",
    (.[] | "| [\(.tag_name)](\(.html_url))\(if .prerelease then " (pre-release)" else "" end) | \(.published_at[0:10]) | \([.assets[] | select(.name | startswith("openblood-")) | "[\(.name | short)](\(.browser_download_url))"] | join(" · ")) |"),
    "",
    "## Release notes",
    "",
    (.[0:20][] | "### \(.tag_name) (\(.published_at[0:10]))", "", ((.body // "") | gsub("\r"; "")), "")
' <<<"$releases"
